<template><section class="scr-card"><h3>{{ t('settings.performance') }}</h3><ToggleField :model-value="settings.performanceProfiling === true" :label="t('settings.profiling')" @update:model-value="value => update('performanceProfiling', value)" /><ToggleField :model-value="settings.diagnosticLogging === true" :label="t('settings.diagnostics')" @update:model-value="value => update('diagnosticLogging', value)" /><div v-if="settings.performanceProfiling" class="scr-form-grid"><NumericInput v-for="field in budgets" :key="field.id" :model-value="Number(settings.performanceBudgets?.[field.id] || field.default)" :label="t(field.label)" :min="0.1" :max="20" :step="0.1" @update:model-value="value => budget(field.id, value)" /></div><DetailsPanel :open="settings.performanceProfiling" :title="t('settings.performance')"><div class="scr-tech-grid"><span v-for="(value, key) in summary" :key="key"><code>{{ key }}</code>: {{ display(value) }}</span></div></DetailsPanel></section></template>
<script setup>import { computed } from "vue"; import { useStores } from "../../stores/index.js"; import ToggleField from "../common/ToggleField.vue"; import NumericInput from "../common/NumericInput.vue"; import DetailsPanel from "../common/DetailsPanel.vue"; const stores = useStores(); const settings = stores.settings.state; const { t } = stores.i18n; const budgets = [{ id: "idleBudgetMs", label: "settings.budgetIdle", default: 0.5 }, { id: "busyBudgetMs", label: "settings.budgetBusy", default: 2.5 }, { id: "raceBudgetMs", label: "settings.budgetRace", default: 3.5 }, { id: "uiPublishBudgetMs", label: "settings.budgetUI", default: 1.5 }, { id: "indexChunkBudgetMs", label: "settings.budgetIndex", default: 2 }]; const summary = computed(() => stores.performance.state.telemetry || stores.performance.state); const display = value => typeof value === "object" ? JSON.stringify(value) : String(value); const update = (field, value) => stores.command.send("updateSettings", [{ [field]: value }]); const budget = (field, value) => update("performanceBudgets", { ...(settings.performanceBudgets || {}), [field]: value })</script>
